@-moz-document domain("www.tumblr.com") {
/* Paint the fixed grid on the actual Tumblr app shell, without a body ID. */
html, html body, body #root, body #root > #base-container,
body #root > #base-container .D5eCV, body#tumblr .GDWdm,
body #root .gPQR5 > .lSyOz,
body #root .gPQR5 > .lSyOz > main,
body #root .gPQR5 > .lSyOz > [role="main"],
body #root .lSyOz .Evcyl,
body #root .lSyOz .Evcyl > .zAlrA,
body .DCCfo {
  background-color: #0a0a0a !important;
  /* Entirely CSS-generated wallpaper: no image URLs or encoded assets. */
  /* Thin pale-green grid at 40px intervals, plus faint 4px CRT scan lines. */
  background-image:
    linear-gradient(to right, rgba(130,255,167,.13) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(130,255,167,.13) 1px, transparent 1px),
    repeating-linear-gradient(to bottom,
      rgba(10,10,10,0) 0px,
      rgba(10,10,10,0) 3px,
      rgba(105,255,153,.035) 3px,
      rgba(105,255,153,.035) 4px) !important;
  background-size: 40px 40px, 40px 40px, 100% 4px !important;
  background-position: 0 0 !important;
  background-repeat: repeat !important;
  background-attachment: fixed !important;
}

/* Clear wrapper paint between the body grid and the feed. */
body #__next, body #tumblr-root, body #tumblr-app,
body#tumblr main > [data-timeline],
body#tumblr main > [data-timeline-id] {
  background-color: transparent !important;
  background-image: none !important;
}
body, body button, body input, body select, body textarea, body nav, body aside,
body article, body header, body [role="menu"], body [role="dialog"],
body [contenteditable="true"], body [role="textbox"] {
  font-family: "Cascadia Mono", "Cascadia Code", "JetBrains Mono", "Consolas", "Lucida Console", "Courier New", monospace !important;
  font-variant-ligatures: none !important;
  font-feature-settings: "zero" 1 !important;
}
body { color: #d9ffe6 !important; }
body small, body time, body figcaption, body [data-testid="tag-link"] {
  color: #9ee5b6 !important;
}
body article p a, body article li a, body [data-testid="post-content"] a {
  color: #7fffac !important;
}
body article p a:hover, body article li a:hover,
body [data-testid="post-content"] a:hover, body [data-testid="tag-link"]:hover {
  color: #00ff66 !important;
  text-decoration: underline !important;
